'use client';

import Link from 'next/link';

import {usePathname,useRouter,useSearchParams} from 'next/navigation';

import {useEffect,useMemo,useState} from 'react';

import {BookmarkSimple,ShareNetwork,ArrowRight,MapPin,Star,Funnel,Info,Trash,Sun,Moon,CheckCircle,TrendUp,TrendDown,ChatCircle,Briefcase,CurrencyRub,Trophy,UsersThree,CalendarBlank,Tag,Bell,Plus,ArrowsDownUp,SquaresFour,Heart,UserCircle,X} from '@phosphor-icons/react';

import {categories,cities,cityName,categoryName} from '@/data/catalog';
import {catalogFiltersFor} from '@/data/category-filters';
import {buildSiteMap,siteMapEntryCount} from '@/data/site-map';

import {profiles,projects,creditsFor,mediaById,services,reviews,ratings,initialNotices,profileBySlug,projectBySlug} from '@/data/seed';

import {useApp} from '@/components/navigation/app-shell';
import type {RatingEntry} from '@/types/domain';

import {ProjectCard,VisualProjectCard,ProfileCard,ProCatalogCard,ProShowcaseRail,formatPrice} from '@/components/cards/cards';
import {SearchDesignControls} from '@/components/pages/search-enhancements';



const qp=(s:URLSearchParams,key:string,fallback='')=>s.get(key)??fallback;

function useUrl(){const router=useRouter();const search=useSearchParams();const path=usePathname();const set=(changes:Record<string,string|null>)=>{const u=new URLSearchParams(window.location.search);Object.entries(changes).forEach(([k,v])=>v?u.set(k,v):u.delete(k));router.push(`${path}?${u.toString()}`)};return{router,search,set}}

const section=(title:string,children:React.ReactNode)=><section className="section"><h2>{title}</h2>{children}</section>;

export function DemoPage({path}:{path:string}){const state=useSearchParams().get('state');if(path!=='/demo'&&['loading','empty','error'].includes(state??''))return <StatePreview path={path} state={state!}/>;if(path==='/feed')return <Feed/>;if(path==='/search')return <Search/>;if(path==='/pro')return <ProHome/>;if(path.startsWith('/pro/'))return <ProCategory slug={decodeURIComponent(path.slice(5))}/>;if(path.startsWith('/projects/'))return <ProjectDetail slug={decodeURIComponent(path.slice(10))}/>;if(path.startsWith('/profiles/'))return <ProfileDetail slug={decodeURIComponent(path.slice(10))}/>;if(path==='/ratings')return <Ratings/>;if(path==='/collections')return <Collections/>;if(path.startsWith('/collections/'))return <CollectionDetail slug={decodeURIComponent(path.slice(13))}/>;if(path==='/me')return <Me/>;if(path==='/notifications')return <Notifications/>;if(path==='/settings')return <Settings/>;if(path==='/register')return <RegisterPage/>;if(path==='/professional')return <ProfessionalPage/>;if(path==='/recommendations')return <Recommendations/>;if(path==='/subscriptions')return <Subscriptions/>;if(path==='/favorites')return <Favorites/>;if(path==='/favorites-pro')return <FavoritesPro/>;if(path==='/platform')return <PlatformPage/>;if(path==='/support')return <SupportPage/>;if(path==='/blog')return <ResourcePage kind='blog'/>;if(path==='/faq')return <ResourcePage kind='faq'/>;if(path==='/knowledge')return <ResourcePage kind='knowledge'/>;if(path==='/video-lessons')return <ResourcePage kind='video-lessons'/>;if(path==='/webinars')return <ResourcePage kind='webinars'/>;if(path==='/api')return <ResourcePage kind='api'/>;if(path==='/complaint')return <ResourcePage kind='complaint'/>;if(path==='/offline')return <OfflinePage/>;if(path==='/404')return <NotFoundPreview/>;if(path==='/error')return <ErrorPreview/>;if(path==='/about')return <About/>;if(path==='/demo')return <DemoHub/>;return <main className="container page"><h1>Страница не найдена</h1><p>Такого адреса в demo нет.</p><Link className="button primary" href="/feed">В ленту</Link></main>}

function StatePreview({path,state}:{path:string;state:string}){const title=state==='loading'?'Загрузка данных':state==='empty'?'Здесь пока пусто':'Не удалось показать данные';return <div className="container page"><div className="eyebrow">Проверка состояния · Demo hub</div><h1>{title}</h1>{state==='loading'?<div className="grid section" role="status" aria-label="Загрузка"><div className="skeleton"/><div className="skeleton"/><div className="skeleton"/></div>:<div className="empty section"><p>{state==='empty'?'Попробуйте другую тему или вернитесь к полной выдаче.':'Локальная симуляция ошибки. Данные не изменены.'}</p><Link className="button primary" href={path}>Повторить и открыть страницу</Link></div>}<div className="section"><Link className="button" href="/demo">Вернуться в demo hub</Link></div></div>}

function Feed(){const app=useApp();const {search,set}=useUrl();const tab=qp(search,'tab','for-you');const topics=['Свадьба','Editorial','Площадки','Beauty','Форум','Декор','Музыка','Кейтеринг'];const ordered=useMemo(()=>{const copy=[...projects];if(tab==='new')copy.reverse();else if(tab==='popular')copy.sort((a,b)=>b.reactions-a.reactions);else copy.sort((a,b)=>(b.city===app.city?1:0)-(a.city===app.city?1:0));return copy},[tab,app.city]);const feed=ordered.flatMap((p,i)=>i<12?[{p,index:0},{p,index:1}]:[{p,index:0}]);return <div className="container page feed-page"><div className="feed-tabs tabs" role="tablist" aria-label="Лента">{[['for-you','Для вас'],['popular','Популярное'],['new','Новое']].map(([v,label])=><button role="tab" aria-selected={tab===v} className={`chip ${tab===v?'selected':''}`} key={v} onClick={()=>set({tab:v})}>{label}</button>)}</div><div className="story-rail" aria-label="Быстрые темы">{topics.slice(0,2).map((t,i)=><Link className="story" key={t} href={`/search?q=${encodeURIComponent(t)}`}><span className="story-images"><span className="story-avatar"><img src={mediaById(projects[i].mediaIds[0]).src} alt=""/></span><img src={mediaById(projects[i+1].mediaIds[0]).src} alt=""/><img src={mediaById(projects[i+2].mediaIds[1]).src} alt=""/><img src={mediaById(projects[i+3].mediaIds[0]).src} alt=""/></span><span>#{t.toLowerCase()}</span></Link>)}</div><div className="section-head feed-heading"><h1>Проекты авторов, на которых вы подписаны, и многое другое</h1><span className="meta">{projects.length} проектов · {cityName(app.city)}</span></div><div className="masonry">{feed.map(({p,index})=><VisualProjectCard key={`${p.id}-${index}`} project={p} mediaIndex={index} />)}</div>{section('Профессионалы рядом с идеей',<div className="grid">{profiles.filter(p=>p.city===app.city).slice(0,4).map(p=><ProfileCard key={p.id} profile={p}/>)}</div>)}</div>}

function ProjectDetail({slug}:{slug:string}){const project=projectBySlug(slug);const app=useApp();const {search,router}=useUrl();if(!project)return <Missing/>;const credits=creditsFor(project.id);const lead=profileBySlug(project.leadProfileId)!;const mediaIndex=Math.min(Number(qp(search,'media','0'))||0,project.mediaIds.length-1);const share=async()=>{try{await navigator.clipboard.writeText(location.href);app.toast('Ссылка скопирована')}catch{app.toast(`Ссылка: ${location.href}`)}};return <div className="container page project-detail-page"><div className="eyebrow"><Link href="/feed">Лента</Link> / Проект</div><div className="project-detail-head"><div><h1>{project.title}</h1><p className="project-lede-meta">{project.eventType} · {cityName(project.city)} · {project.date.slice(0,4)} · Демо-проект</p><div className="project-tag-row" aria-label="Стили и теги проекта">{project.styles.map(style=><Link className="chip" href={`/search?q=${encodeURIComponent(style)}`} key={style}>{style}</Link>)}</div></div><div className="row project-detail-actions"><button className="button" onClick={()=>app.open('save',{projectId:project.id})}><BookmarkSimple size={18}/> Сохранить</button><button className="button" onClick={share}><ShareNetwork size={18}/> Поделиться</button></div></div><div className="split project-detail-layout"><div><div className="gallery project-gallery">{project.mediaIds.slice(0,5).map((id,i)=>{const m=mediaById(id);return <button key={id} onClick={()=>{router.replace(`/projects/${slug}?media=${i}`);app.open('media',{projectId:project.id,mediaIndex:i})}} aria-label={`Открыть кадр ${i+1}: ${m.caption}`}><img src={m.src} alt={m.alt}/>{i===4&&<span className="demo-label">Все {project.mediaIds.length} кадров</span>}</button>})}</div><div className="rail project-media-rail">{project.mediaIds.map((id,i)=><button key={id} className="icon-btn" aria-label={`Кадр ${i+1}`} onClick={()=>app.open('media',{projectId:project.id,mediaIndex:i})} style={{overflow:'hidden',padding:0,minWidth:72,width:72,height:56,borderColor:i===mediaIndex?'var(--brand-pro)':undefined}}><img src={mediaById(id).src} alt="" style={{width:'100%',height:'100%',objectFit:'cover'}}/></button>)}</div>{section('О проекте',<><div className="project-facts" aria-label="Параметры проекта"><span><b><Tag size={14}/> Формат</b>{project.eventType}</span><span><b><MapPin size={14}/> Где</b>{cityName(project.city)}</span><span><b><CalendarBlank size={14}/> Когда</b>{project.date.slice(0,4)}</span><span><b><UsersThree size={14}/> Команда</b>{credits.length} участников</span></div><p className="lede">{project.description}</p><div className="rail project-tag-row">{project.tags.map(tag=><Link className="chip" href={`/search?q=${encodeURIComponent(tag)}`} key={tag}>{tag}</Link>)}</div></>)}<section className="section" id="team"><div className="section-head"><div><div className="eyebrow">Credits</div><h2>Команда проекта</h2></div><span className="meta">{credits.length} участников</span></div><p>Каждый участник связан с полным профилем, услугами и условиями работы.</p><div className="credit-grid project-credit-grid">{credits.map(c=>{const p=profileBySlug(c.profileId)!;const reviewCount=reviews.filter(r=>r.profileId===p.id).length;return <article className="card credit project-credit-card" key={c.id} tabIndex={0} role="link" aria-label={`Открыть профиль ${p.name}`} onClick={e=>{if((e.target as HTMLElement).closest('a,button'))return;router.push(`/profiles/${p.slug}?from=projects/${project.slug}`)}} onKeyDown={e=>{if(e.key==='Enter')router.push(`/profiles/${p.slug}?from=projects/${project.slug}`)}}><div className="between credit-card-top"><img className="avatar" src={p.avatar} alt=""/><span className="badge">{c.roleLabel}</span></div><div><h3><Link href={`/profiles/${p.slug}?from=projects/${project.slug}`}>{p.name}</Link></h3><p>{c.contribution}</p><div className="credit-card-facts"><span className="icon-meta"><MapPin size={14}/> {cityName(p.city)}</span><span className="icon-meta"><Star size={14} weight="fill"/> {p.rating.toFixed(1)} <ChatCircle size={13}/> {reviewCount}</span><span className="icon-meta"><CurrencyRub size={14}/> {formatPrice(p.price)}</span></div><div className="row credit-card-actions"><Link className="button" href={`/profiles/${p.slug}?from=projects/${project.slug}`}>Открыть профиль <ArrowRight size={16}/></Link><button className="icon-btn" aria-label={`Связаться с ${p.name}`} title={`Связаться с ${p.name}`} onClick={()=>app.open('contact',{profileId:p.id,projectId:project.id})}><ShareNetwork size={17}/></button></div></div></article>})}</div></section>{section('Собрать похожую команду',<div className="grid related-profile-grid">{profiles.filter(p=>!credits.some(c=>c.profileId===p.id)&&p.city===project.city).slice(0,4).map(p=><div key={p.id}><ProfileCard profile={p}/><p className="meta related-profile-reason">Подходит по городу и дополняет команду проекта</p></div>)}</div>)}</div><aside className="sidebar project-sidebar"><div className="card card-body project-summary-card"><div className="eyebrow">Общее авторство</div><div className="row"><img className="avatar" src={lead.avatar} alt=""/><div><b>{lead.name}</b><div className="meta">и ещё {credits.length-1} участников</div></div></div><div className="project-summary-metrics"><span className="icon-meta"><Heart size={15}/><b>{project.reactions}</b> реакций</span><span className="icon-meta"><BookmarkSimple size={15}/><b>{project.saves}</b> сохранений</span></div><button className="button primary" style={{width:'100%'}} onClick={()=>document.getElementById('team')?.scrollIntoView({behavior:'smooth'})}>Смотреть всю команду</button><button className="button" style={{width:'100%',marginTop:8}} onClick={()=>app.open('contact',{profileId:lead.id,projectId:project.id})}>Связаться с организатором</button></div></aside></div><div className="sticky-actions project-actions-mobile"><span className="sticky-project-title">{project.title}</span><button className="button" onClick={()=>app.open('save',{projectId:project.id})}>Сохранить</button><button className="button pro" onClick={()=>app.open('contact',{profileId:lead.id,projectId:project.id})}>Связаться с командой</button></div></div>}
function ProfileDetail({slug}:{slug:string}){const p=profileBySlug(slug);const app=useApp();const {search,set}=useUrl();const [subscribed,setSubscribed]=useState(false);useEffect(()=>{try{const raw=localStorage.getItem('chereda-subscriptions');if(raw)queueMicrotask(()=>setSubscribed((JSON.parse(raw) as string[]).includes(p?.id??'')))}catch{}},[p?.id]);const toggleSubscription=()=>{if(!p)return;const raw=localStorage.getItem('chereda-subscriptions');const ids=raw?JSON.parse(raw) as string[]:[];const next=subscribed?ids.filter(id=>id!==p.id):[...new Set([...ids,p.id])];localStorage.setItem('chereda-subscriptions',JSON.stringify(next));setSubscribed(!subscribed);app.toast(subscribed?'Подписка снята':'Профиль добавлен в подписки')};if(!p)return <Missing/>;const tab=qp(search,'tab','projects');const serviceList=services.filter(s=>s.profileId===p.id);const reviewList=reviews.filter(r=>r.profileId===p.id);const reviewFilter=qp(search,'review','all');const filteredReviews=reviewFilter==='projects'?reviewList.filter(r=>r.projectId):reviewList;const entry=ratings.find(r=>r.profileId===p.id);const fromProject=search.get('from')?.split('/')[1];const share=async()=>{try{await navigator.clipboard.writeText(location.href);app.toast('Ссылка скопирована')}catch{app.toast(`Ссылка: ${location.href}`)}};const travel=p.travel==='nearby'?'выезд до 80 км':p.travel==='countrywide'?'по всей России':p.travel==='international'?'международные проекты':p.travel==='remote'?'онлайн':'в городе';const kind=p.type==='venue'?'Площадка':p.type==='company'?'Команда':p.type==='team'?'Команда':'Специалист';return <div className="container page profile-detail-page"><div className="eyebrow"><Link href="/pro">PRO</Link> / {categoryName(p.category)}</div><div className="profile-detail-actions"><span className="profile-kind-label">{kind} · {p.subcategory}</span><div className="row"><button className="button" onClick={()=>app.open('save',{projectId:p.projectIds[0]})}><BookmarkSimple size={18}/> Сохранить кейс</button><button className="button" onClick={share}><ShareNetwork size={18}/> Поделиться</button></div></div><div className="profile-hero"><img className="profile-cover" src={p.cover} alt={`Демо-обложка ${p.name}`}/><div className="profile-heading"><img className="avatar large" src={p.avatar} alt=""/><div><div className="profile-title-line"><h1>{p.name}</h1>{p.verified&&<span className="badge verified"><CheckCircle size={15}/> Проверен</span>}</div><div className="meta">{p.specialty} · {cityName(p.city)}</div></div></div></div><div className="facts profile-facts"><span className="fact" title="Основной город и условия выезда"><MapPin size={16}/> {cityName(p.city)} · {travel}</span><span className="fact icon-meta" title="Основная опубликованная цена"><CurrencyRub size={16}/> {formatPrice(p.price)}</span><button className="fact" title="Открыть состав рейтинга" onClick={()=>app.open('score',{profileId:p.id})}><Star size={16}/> {p.rating.toFixed(1)} · {(entry?.score??p.score).toLocaleString('ru-RU')} баллов</button><Link className="fact" href={`/ratings?category=${p.category}&city=${p.city}`}>Рейтинг категории →</Link><span className="fact icon-meta"><ChatCircle size={16}/> <b>{reviewList.length}</b> отзывов</span><span className="fact icon-meta"><Briefcase size={16}/> <b>{p.projectIds.length}</b> проектов</span><span className="fact icon-meta"><UsersThree size={16}/> <b>{serviceList.length}</b> услуг</span></div><div className="profile-intro between wrap"><div><p className="lede">{p.bio}</p><div className="profile-style-row" aria-label="Стили профиля">{p.styles.map(style=><Link className="chip" href={`/search?q=${encodeURIComponent(style)}`} key={style}>{style}</Link>)}</div></div><div className="row wrap"><button className="button" onClick={toggleSubscription}>{subscribed ? "Вы подписаны" : "Подписаться"}</button><button className="button pro" onClick={()=>app.open('contact',{profileId:p.id,projectId:fromProject})}>Связаться</button></div></div><div className="tabs section profile-tabs" role="tablist" aria-label="Разделы профиля">{[['projects','Проекты'],['services','Услуги'],['about','О профиле'],['reviews','Отзывы']].map(([v,label])=><button role="tab" aria-selected={tab===v} key={v} className={`chip ${tab===v?'selected':''}`} onClick={()=>set({tab:v})}>{label}</button>)}</div>{tab==='projects'&&<section className="section profile-projects-section"><div className="section-head"><div><div className="eyebrow">Портфолио</div><h2>Проекты с участием профиля</h2></div><span className="meta">{p.projectIds.length} кейса</span></div><div className="grid profile-projects-grid">{p.projectIds.map(id=>projects.find(pr=>pr.id===id)!).filter(Boolean).slice(0,8).map(pr=><div className="profile-project-wrap" key={pr.id}><ProjectCard project={pr}/><span className="profile-project-role">Участник проекта</span></div>)}</div></section>}{tab==='services'&&<section className="section"><div className="section-head"><div><div className="eyebrow">Работа</div><h2>Услуги и цены</h2></div><span className="meta">{serviceList.length} предложения</span></div><div className="grid profile-services-grid">{serviceList.map((s,i)=><article className="card card-body service-card" key={s.id}><div className="between"><span className="badge">{i===0?'Основная услуга':'Дополнительная'}</span><span className="meta">{cityName(p.city)}</span></div><h3>{s.name}</h3><p>{s.description}</p><div className="service-meta"><span>Формат: по запросу</span><span>{travel}</span></div><div className="between service-card-footer"><b>{formatPrice(s.price)}</b><button className="button" onClick={()=>app.open('contact',{profileId:p.id,serviceId:s.id,projectId:fromProject})}>Выбрать услугу</button></div></article>)}</div></section>}{tab==='about'&&<section className="section profile-about-section"><div className="eyebrow">Профиль</div><h2>О профиле</h2><p className="lede">{p.bio} Условия работы согласуются до события. В demo можно сохранить заявку локально и вернуться к проекту.</p><div className="profile-about-grid"><article className="card card-body"><h3>География и формат</h3><p>{cityName(p.city)} · {travel}</p><p>Цена: {formatPrice(p.price)}</p></article><article className="card card-body"><h3>Специализация</h3><p>{p.specialty} · {p.subcategory}</p><div className="profile-style-row">{p.styles.map(style=><span className="chip" key={style}>{style}</span>)}</div></article></div></section>}{tab==='reviews'&&<section className="section profile-reviews-section" id="profile-reviews"><div className="section-head"><div><div className="eyebrow">Доверие</div><h2>Отзывы</h2></div><span className="profile-review-score"><Star size={16} weight="fill"/> {p.rating.toFixed(1)} · {reviewList.length}</span></div><div className="review-summary"><div className="review-summary-score"><b>{p.rating.toFixed(1)}</b><span>средняя оценка</span></div><div className="review-distribution">{[5,4,3].map(value=><div key={value}><span className="icon-meta"><Star size={12} weight="fill"/> {value}</span><i><em style={{width:`${value===5?'78':value===4?'48':'16'}%`}}/></i></div>)}</div></div><div className="tabs review-filters" role="tablist" aria-label="Фильтр отзывов">{[['all','Все'],['projects','По проектам']].map(([v,label])=><button role="tab" aria-selected={reviewFilter===v} className={`chip ${reviewFilter===v?'selected':''}`} key={v} onClick={()=>set({tab:'reviews',review:v})}>{label}</button>)}</div>{filteredReviews.length?<div className="stack profile-review-list">{filteredReviews.map(r=><article className="card card-body review-card" key={r.id}><div className="between"><div><b>{r.author}</b><div className="meta">{r.date} · {projects.find(pr=>pr.id===r.projectId)?.title}</div></div><span className="review-stars icon-meta"><Star size={13} weight="fill"/> {r.rating}</span></div><p>{r.text}</p><Link className="meta" href={`/projects/${r.projectId}`}>Открыть проект <ArrowRight size={14}/></Link></article>)}</div>:<div className="empty"><p>Для этого фильтра отзывов пока нет.</p><button className="button" onClick={()=>set({tab:'reviews',review:'all'})}>Показать все отзывы</button></div>}</section>}{section('Похожие профессионалы',<div className="grid related-profile-grid">{profiles.filter(other=>other.category===p.category&&other.id!==p.id).slice(0,4).map(other=><ProfileCard profile={other} key={other.id}/>)}</div>)}<div className="sticky-actions profile-sticky-actions"><span className="sticky-profile-price">{formatPrice(p.price)}</span><button className="button pro" onClick={()=>app.open('contact',{profileId:p.id,projectId:fromProject})}>Связаться</button></div></div>}
function Missing(){return <div className="container page"><h1>Страница не найдена в demo</h1><p>Попробуйте другой адрес.</p><Link className="button" href="/feed">Вернуться в ленту</Link></div>}
function Search(){const app=useApp();const {search,set,router}=useUrl();const [query,setQuery]=useState(qp(search,'q'));const tab=qp(search,'tab','all');const q=qp(search,'q').trim().toLowerCase();const city=qp(search,'city',app.city);const category=qp(search,'category');const selectedStyles=(search.get('styles')??'').split(',').map(v=>v.trim()).filter(Boolean);const sort=qp(search,'sort','recommended');const [filterOpen,setFilterOpen]=useState(false);useEffect(()=>{queueMicrotask(()=>setQuery(qp(search,'q')))},[search]);const projectResults=projects.filter(p=>(!q||`${p.title} ${p.description} ${p.eventType} ${p.styles.join(' ')}`.toLowerCase().includes(q))&&(!search.get('city')||p.city===city)&&(!selectedStyles.length||selectedStyles.some(s=>p.styles.includes(s))));const profileResults=profiles.filter(p=>(!q||`${p.name} ${p.specialty} ${p.bio} ${categoryName(p.category)}`.toLowerCase().includes(q))&&(!category||p.category===category)&&(!search.get('city')||p.city===city)&&(!selectedStyles.length||selectedStyles.some(s=>p.styles.includes(s))));const resultCount=(tab==='projects'?projectResults.length:tab==='profiles'?profileResults.length:projectResults.length+profileResults.length);return <div className={"container page search-page "+(q?"has-query":"")}><div className="hero"><div className="eyebrow">Поиск Chereda</div><h1>Найдите идею или специалиста</h1><p>Один запрос соединяет проекты и людей, которые над ними работали.</p><form className="searchbar" onSubmit={e=>{e.preventDefault();set({q:query||null})}}><input className="input" aria-label="Поисковый запрос" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Например, Белый сад или укладка"/><button className="button primary" type="submit">Найти</button></form></div><div className="rail section">{['Белый сад','укладка','лофт','editorial','кейтеринг'].map(v=><button className="chip" key={v} onClick={()=>{setQuery(v);set({q:v})}}>{v}</button>)}</div><div className="section-head"><div><h2>{q||search.toString()?'Результаты поиска':'Начните с направления'}</h2><span className="meta" aria-live="polite">{resultCount} результатов</span></div><button className="button mobile-filter" onClick={()=>setFilterOpen(true)}><Funnel size={18}/> Фильтры</button></div><div className="filter-layout"><aside className="filter-panel desktop-filter"><h2>Фильтры</h2><label className="field">Категория<select className="select" value={category} onChange={e=>set({category:e.target.value||null})}><option value="">Все категории</option>{categories.map(c=><option value={c.slug} key={c.slug}>{c.name}</option>)}</select></label><label className="field">Город<select className="select" value={search.get('city')??''} onChange={e=>set({city:e.target.value||null})}><option value="">Все города</option>{cities.map(c=><option value={c.slug} key={c.slug}>{c.name}</option>)}</select></label><button className="button" onClick={()=>router.push('/search')}>Сбросить фильтры</button></aside><div><SearchDesignControls/><div className="between wrap" style={{marginBottom:16}}><div className="tabs" role="tablist" aria-label="Типы результатов">{[['all','Всё'],['projects','Проекты'],['profiles','Профили']].map(([v,label])=><button role="tab" aria-selected={tab===v} key={v} className={`chip ${tab===v?'selected':''}`} onClick={()=>set({tab:v})}>{label}</button>)}</div><label className="field" style={{minWidth:180}}>Сортировка<select className="select" value={sort} onChange={e=>set({sort:e.target.value})}><option value="recommended">По релевантности</option><option value="new">Новые</option><option value="rating">По рейтингу</option></select></label></div><div className="rail">{[q&&`Запрос: ${q}`,search.get('city')&&`Город: ${cityName(city)}`,category&&`Категория: ${categoryName(category)}`].filter(Boolean).map(s=><span className="chip" key={s}>{s}</span>)}</div>{resultCount===0?<div className="empty"><h3>Ничего не найдено</h3><p>Попробуйте другой запрос или снимите часть фильтров.</p><button className="button" onClick={()=>router.push('/search')}>Сбросить фильтры</button></div>:<>{(tab==='all'||tab==='projects')&&projectResults.length>0&&section('Проекты',<div className="grid">{projectResults.slice(0,12).map(p=><ProjectCard project={p} key={p.id}/>)}</div>)}{(tab==='all'||tab==='profiles')&&profileResults.length>0&&section('Профессионалы',<div className="result-grid">{[...profileResults].sort((a,b)=>sort==='rating'?b.score-a.score:0).slice(0,18).map(p=><ProfileCard profile={p} key={p.id}/>)}</div>)}</>}</div></div>{filterOpen&&<div className="overlay" onMouseDown={e=>{if(e.target===e.currentTarget)setFilterOpen(false)}}><div className="dialog sheet" role="dialog" aria-modal="true" aria-label="Фильтры поиска"><div className="between"><h2>Фильтры</h2><button className="icon-btn" onClick={()=>setFilterOpen(false)} aria-label="Закрыть"><X size={18}/></button></div><label className="field">Категория<select className="select" value={category} onChange={e=>set({category:e.target.value||null})}><option value="">Все категории</option>{categories.map(c=><option value={c.slug} key={c.slug}>{c.name}</option>)}</select></label><label className="field">Город<select className="select" value={search.get('city')??''} onChange={e=>set({city:e.target.value||null})}><option value="">Все города</option>{cities.map(c=><option value={c.slug} key={c.slug}>{c.name}</option>)}</select></label><button className="button primary" style={{width:'100%',marginTop:16}} onClick={()=>setFilterOpen(false)}>Показать {resultCount} результатов</button></div></div>}</div>}

function ProHome(){const showcase=[...profiles.filter(p=>p.category==='venues'),...profiles.filter(p=>p.category==='photo-video').slice(0,2)];return <div className="container page pro-home"><h1 className="sr-only">Каталог профессионалов</h1><div className="pro-taxonomy pro-home-taxonomy"><Link href="/pro" className="active">Все</Link>{categories.map(c=><Link href={`/pro/${c.slug}`} key={c.slug}>{c.name}</Link>)}</div><div className="section-head pro-home-heading"><div><h1>Популярные</h1><span className="meta">Площадки</span></div><Link className="button" href="/pro/venues">Все площадки <ArrowRight size={16}/></Link></div><ProShowcaseRail profiles={[...showcase,...showcase].slice(0,6)}/><section className="pro-home-next section"><div><h2>Найдите специалиста под задачу</h2><p>Выберите категорию, задайте город, условия работы и нужный формат карточек.</p></div><Link className="button pro" href="/pro/venues">Открыть фильтры <ArrowRight size={16}/></Link></section></div>}

function ProCategory({slug}:{slug:string}){
  const category=categories.find(c=>c.slug===slug)
  const app=useApp()
  const {search,set,router}=useUrl()
  const [filterOpen,setFilterOpen]=useState(false)
  if(!category)return <Missing/>
  const subcategory=qp(search,'subcategory')
  const city=qp(search,'city')
  const priceMax=Number(qp(search,'priceMax'))||Infinity
  const priceMin=Number(qp(search,'priceMin'))||0
  const priceUnit=qp(search,'priceUnit')
  const withReviews=qp(search,'reviews')==='1'
  const withPortfolio=qp(search,'portfolio')==='1'
  const pricePublished=qp(search,'priced')==='1'
  const venueType=qp(search,'venueType')
  const equipment=qp(search,'equipment')
  const kitchen=qp(search,'kitchen')
  const parkingMin=Number(qp(search,'parking'))||0
  const outdoor=qp(search,'outdoor')==='1'
  const accommodation=qp(search,'accommodation')==='1'
  const capacity=qp(search,'capacity')
  const outside=qp(search,'outsideCatering')
  const rating=Number(qp(search,'rating'))||0
  const travel=qp(search,'travel')
  const style=qp(search,'styles')
  const sort=qp(search,'sort','recommended')
  const view=qp(search,'view','standard')
  const update=(key:string,value:string)=>set({[key]:value||null})
  const dynamicFilters=catalogFiltersFor(slug,subcategory||undefined).filter(filter=>!['Расположение','Стоимость','Есть Отзывы','Есть фото','Есть Видео','Есть Портфолио','Есть записи в портфолио','Указан гонорар','Вместимость','Сторонний кейтеринг'].includes(filter.label))
  const dynamicApplied:{label:string;key:string}[]=[]
  const dynamicSelections:string[]=[]
  dynamicFilters.forEach(filter=>{
    const key='cf_'+filter.key
    if(filter.type==='group')filter.values.forEach((value,index)=>{if(search.get(`${key}_${index}`)==='1')dynamicSelections.push(value);dynamicApplied.push({label:`${filter.label}: ${value}`,key:`${key}_${index}`})})
    else {const value=search.get(key);if(value)dynamicApplied.push({label:`${filter.label}: ${value}`,key})}
  })
  let list=profiles.filter(p=>p.category===slug&&(!subcategory||p.subcategory===subcategory)&&(!dynamicSelections.length||dynamicSelections.every(value=>p.catalogTags?.includes(value)))&&(!city||p.city===city||p.travel==='countrywide'||(p.travel==='nearby'&&p.city===city))&&(!Number.isFinite(priceMax)||(p.price.kind!=='request'&&(p.price.from??Infinity)<=priceMax))&&(p.price.kind==='request'||(p.price.from??0)>=priceMin)&&(!priceUnit||p.price.unit===priceUnit)&&(!withReviews||reviews.some(r=>r.profileId===p.id))&&(!withPortfolio||p.projectIds.length>0)&&(!pricePublished||p.price.kind!=='request')&&(!venueType||p.venueType===venueType)&&(!equipment||p.equipment?.includes(equipment))&&(!kitchen||p.kitchen===kitchen)&&(!parkingMin||((p.parkingSpaces??0)>=parkingMin))&&(!outdoor||p.outdoor===true)&&(!accommodation||p.accommodation===true)&&(!capacity||(p.capacity!==undefined&&p.capacity>=Number(capacity.split('-')[0])))&&(!outside||p.outsideCatering===true)&&p.rating>=rating&&(!travel||p.travel===travel)&&(!style||p.styles.includes(style)))
  if(sort==='rating')list.sort((a,b)=>b.score-a.score)
  if(sort==='priceAsc')list.sort((a,b)=>(a.price.from??Infinity)-(b.price.from??Infinity))
  if(sort==='priceDesc')list.sort((a,b)=>(b.price.from??-1)-(a.price.from??-1))
  if(sort==='reviews')list.sort((a,b)=>reviews.filter(r=>r.profileId===b.id).length-reviews.filter(r=>r.profileId===a.id).length)
  if(sort==='new')list=[...list].reverse()
  if(search.get('verified')==='1')list=list.filter(p=>p.verified)
  const baseApplied=[
    subcategory&&{label:`Раздел: ${subcategory}`,key:'subcategory'},city&&{label:`Город: ${cityName(city)}`,key:'city'},capacity&&{label:`Гости: ${capacity}`,key:'capacity'},search.get('priceMin')&&{label:`От ${Number(search.get('priceMin')).toLocaleString('ru-RU')} ₽`,key:'priceMin'},search.get('priceMax')&&{label:`До ${Number(search.get('priceMax')).toLocaleString('ru-RU')} ₽`,key:'priceMax'},priceUnit&&{label:`Единица: ${priceUnit}`,key:'priceUnit'},outside&&{label:'Сторонний кейтеринг',key:'outsideCatering'},rating&&{label:`Рейтинг ${rating}+`,key:'rating'},travel&&{label:`Выезд: ${travel}`,key:'travel'},style&&{label:`Стиль: ${style}`,key:'styles'},search.get('verified')==='1'&&{label:'Проверенные профили',key:'verified'},venueType&&{label:`Тип: ${venueType}`,key:'venueType'},equipment&&{label:`Оснащение: ${equipment}`,key:'equipment'},kitchen&&{label:`Кухня: ${kitchen}`,key:'kitchen'},parkingMin&&{label:`Парковка от: ${parkingMin}`,key:'parking'},outdoor&&{label:'Открытая территория',key:'outdoor'},accommodation&&{label:'Проживание',key:'accommodation'},withReviews&&{label:'Есть отзывы',key:'reviews'},withPortfolio&&{label:'Есть проекты',key:'portfolio'},pricePublished&&{label:'Цена указана',key:'priced'}
  ].filter(Boolean) as {label:string;key:string}[]
  const appliedFilters=[...baseApplied,...dynamicApplied]
  const dynamicFields=<>{dynamicFilters.map(filter=>{const key='cf_'+filter.key;if(filter.type==='group')return <fieldset className="catalog-filter-group" key={filter.key}><legend>{filter.label}</legend>{filter.values.map((value,index)=><label className="row" key={value}><input type="checkbox" checked={search.get(`${key}_${index}`)==='1'} onChange={e=>update(`${key}_${index}`,e.target.checked?'1':'')}/>{value}</label>)}</fieldset>;if(filter.type==='checkbox')return <label className="row" key={filter.key}><input type="checkbox" checked={search.get(key)==='1'} onChange={e=>update(key,e.target.checked?'1':'')}/>{filter.label}</label>;if(filter.type==='range')return <label className="field" key={filter.key}>{filter.label}<input className="input" type="text" placeholder={filter.sourceValue||'Введите значение'} defaultValue={search.get(key)??''} key={search.get(key)??''} onBlur={e=>update(key,e.target.value)}/><small>{filter.sourceType||'Диапазон из каталога'}</small></label>;return <label className="field" key={filter.key}>{filter.label}<select className="select" value={search.get(key)??''} onChange={e=>update(key,e.target.value)}><option value="">Любой вариант</option>{filter.values.map(value=><option value={value} key={value}>{value}</option>)}</select></label>})}</>
  const fields=<><label className="field">Город<select className="select" value={city} onChange={e=>update('city',e.target.value)}><option value="">Все города</option>{cities.map(c=><option value={c.slug} key={c.slug}>{c.name}</option>)}</select></label>{slug==='venues'&&<label className="field">Вместимость<select className="select" value={capacity} onChange={e=>update('capacity',e.target.value)}><option value="">Любая</option><option value="20-80">20–80 гостей</option><option value="80-150">80–150 гостей</option><option value="150-300">150–300 гостей</option></select></label>}{slug==='venues'&&<><label className="field">Тип площадки<select className="select" value={venueType} onChange={e=>update('venueType',e.target.value)}><option value="">Любой</option><option value="Лофт">Лофт</option><option value="Бизнес-площадка">Бизнес-площадка</option></select></label><label className="field">Парковка от, мест<input className="input" type="number" min="0" value={search.get('parking')??''} onChange={e=>update('parking',e.target.value)}/></label><label className="field">Оснащение<select className="select" value={equipment} onChange={e=>update('equipment',e.target.value)}><option value="">Любое</option><option value="свет">Свет</option><option value="звук">Звук</option><option value="мебель">Мебель</option><option value="Wi‑Fi">Wi‑Fi</option></select></label><label className="field">Кухня<select className="select" value={kitchen} onChange={e=>update('kitchen',e.target.value)}><option value="">Любая</option><option value="own">Собственная</option><option value="prep">Доготовочная</option><option value="none">Нет</option></select></label><label className="row"><input type="checkbox" checked={outdoor} onChange={e=>update('outdoor',e.target.checked?'1':'')}/> Открытая территория</label><label className="row"><input type="checkbox" checked={accommodation} onChange={e=>update('accommodation',e.target.checked?'1':'')}/> Проживание</label></>}{dynamicFields}<label className="field">Бюджет от, ₽<input className="input" inputMode="numeric" type="number" min="0" placeholder="Например, 100000" defaultValue={search.get('priceMin')??''} key={search.get('priceMin')??''} onBlur={e=>update('priceMin',e.target.value)} onKeyDown={e=>{if(e.key==='Enter')update('priceMin',(e.target as HTMLInputElement).value)}}/></label><label className="field">Бюджет до, ₽<input className="input" inputMode="numeric" type="number" min="0" placeholder="Например, 500000" defaultValue={search.get('priceMax')??''} key={search.get('priceMax')??''} onBlur={e=>update('priceMax',(e.target as HTMLInputElement).value)} onKeyDown={e=>{if(e.key==='Enter')update('priceMax',(e.target as HTMLInputElement).value)}}/></label><label className="field">Единица<select className="select" value={priceUnit} onChange={e=>update('priceUnit',e.target.value)}><option value="">Любая</option><option value="project">За проект</option><option value="hour">За час</option><option value="person">За человека</option><option value="shift">За смену</option></select></label>{slug==='venues'&&<label className="row"><input type="checkbox" checked={outside==='1'} onChange={e=>update('outsideCatering',e.target.checked?'1':'')}/> Сторонний кейтеринг</label>}<label className="field">Выезд<select className="select" value={travel} onChange={e=>update('travel',e.target.value)}><option value="">Любой</option><option value="local">В городе</option><option value="nearby">Рядом</option><option value="countrywide">По России</option><option value="international">По миру</option><option value="remote">Онлайн</option></select></label><label className="field">Стиль<select className="select" value={style} onChange={e=>update('styles',e.target.value)}><option value="">Любой</option>{['editorial','botanical','современный','classic'].map(v=><option key={v} value={v}>{v}</option>)}</select></label><label className="field">Рейтинг<select className="select" value={qp(search,'rating')} onChange={e=>update('rating',e.target.value)}><option value="">Любой</option><option value="4.5">4.5+</option><option value="4.8">4.8+</option></select></label><label className="row"><input type="checkbox" checked={search.get('verified')==='1'} onChange={e=>update('verified',e.target.checked?'1':'')}/> Проверенные профили</label><label className="row"><input type="checkbox" checked={withReviews} onChange={e=>update('reviews',e.target.checked?'1':'')}/> Есть отзывы</label><label className="row"><input type="checkbox" checked={withPortfolio} onChange={e=>update('portfolio',e.target.checked?'1':'')}/> Есть проекты</label><label className="row"><input type="checkbox" checked={pricePublished} onChange={e=>update('priced',e.target.checked?'1':'')}/> Цена указана</label><button className="button" onClick={()=>router.push(`/pro/${slug}`)}>Сбросить фильтры</button></>
  return <div className="container page pro-page"><div className="pro-taxonomy">{categories.map(c=><Link href={`/pro/${c.slug}`} key={c.slug} className={c.slug===slug?'active':''}>{c.name}</Link>)}</div><div className="eyebrow"><Link href="/pro">PRO-каталог</Link> / {category.name}</div><h1>{category.name}</h1><p className="lede">{category.subcategories.join(' · ')}</p><div className="rail section">{category.subcategories.map(sub=><button className={`chip ${subcategory===sub?'selected':''}`} key={sub} onClick={()=>update('subcategory',subcategory===sub?'':sub)}>{sub}</button>)}</div><div className="section-head"><div><h2>Профессионалы</h2><span className="meta icon-meta" aria-live="polite"><SquaresFour size={15}/> {list.length} вариантов</span></div><button className="button mobile-filter" onClick={()=>setFilterOpen(true)}><Funnel size={18}/> Фильтры</button></div><div className="rail" aria-label="Применённые фильтры">{appliedFilters.length?<>{appliedFilters.map(item=><button className="chip selected filter-chip" key={item.key} onClick={()=>update(item.key,'')}>{item.label}<X size={13} aria-hidden="true"/></button>)}<button className="text-button" onClick={()=>router.push(`/pro/${slug}`)}>Сбросить все</button></>:<span className="meta">Фильтры не применены</span>}</div><div className="filter-layout"><aside className="filter-panel desktop-filter"><h2>Фильтры</h2>{fields}</aside><div><div className="between wrap" style={{marginBottom:16}}><span className="meta">Каталог фильтров: {catalogFiltersFor(slug,subcategory||undefined).length} параметров · цена, город и рейтинг видны в карточке</span><div className="pro-view-controls"><label className="field" style={{minWidth:220}}><span className="icon-meta"><ArrowsDownUp size={14}/> Сортировка</span><select className="select" value={sort} onChange={e=>update('sort',e.target.value)}><option value="recommended">Рекомендуемое</option><option value="rating">По рейтингу</option><option value="priceAsc">Цена: сначала ниже</option><option value="priceDesc">Цена: сначала выше</option><option value="reviews">Больше отзывов</option><option value="new">Новые</option></select></label><label className="field" style={{minWidth:150}}><span className="icon-meta"><SquaresFour size={14}/> Вид</span><select className="select" value={view} onChange={e=>update('view',e.target.value)}><option value="standard">Стандартно</option><option value="compact">Компактно</option><option value="visual">Крупно</option></select></label></div></div>{list.length?<div className={`result-grid pro-results view-${view}`}>{list.map(p=><ProCatalogCard key={p.id} profile={p} variant={view==='compact'?'compact':view==='visual'?'visual':'standard'}/>)}</div>:<div className="empty"><h3>Нет вариантов по этим условиям</h3><p>Снимите наиболее ограничивающий фильтр или выберите другой город.</p><button className="button" onClick={()=>router.push(`/pro/${slug}`)}>Сбросить фильтры</button></div>}<div className="section"><Link className="button" href={`/ratings?category=${slug}&city=${city||app.city}`}>Сравнить рейтинг <ArrowRight size={16}/></Link></div></div></div>{filterOpen&&<div className="overlay" onMouseDown={e=>{if(e.target===e.currentTarget)setFilterOpen(false)}}><div className="dialog sheet" role="dialog" aria-modal="true" aria-label="Фильтры категории"><div className="between"><h2>Фильтры</h2><button className="icon-btn" aria-label="Закрыть" onClick={()=>setFilterOpen(false)}><X size={18}/></button></div><div className="stack">{fields}</div><button className="button primary" style={{width:'100%',marginTop:20}} onClick={()=>setFilterOpen(false)}>Показать {list.length} вариантов</button></div></div>}</div>
}function Ratings(){const app=useApp();const {search,set,router}=useUrl();const category=qp(search,'category');const city=qp(search,'city',app.city);const period=qp(search,'period','month');let list=ratings.filter(r=>(!category||r.category===category)&&(!city||r.city===city)).sort((a,b)=>b.score-a.score);const fallback=list.length===0;const fallbackList=ratings.filter(r=>!category||r.category===category).sort((a,b)=>b.score-a.score);if(fallback)list=fallbackList;const top=list.slice(0,3);const selectedCity=cityName(city);const periodLabel=period==='year'?'Год':'Месяц';const factorLabels:{key:keyof RatingEntry['breakdown'];label:string;help:string}[]=[{key:'reviews',label:'Отзывы',help:'Количество и качество отзывов.'},{key:'verification',label:'Проверка',help:'Подтверждение профиля и данных.'},{key:'projects',label:'Проекты',help:'Связные проекты и credits.'},{key:'activity',label:'Активность',help:'Актуальность профиля и участия.'},{key:'engagement',label:'Интерес аудитории',help:'Сохранения и переходы в demo.'}];return <div className="container page ratings-page"><div className="ratings-intro"><div><div className="eyebrow">Доверие · Демо-методика</div><h1>Рейтинг профессионалов</h1><p className="lede">Сравнивайте специалистов по объяснимому score: отзывам, проверке, проектам, активности и интересу аудитории. Рейтинг помогает сузить выбор, но не гарантирует качество услуги.</p></div><a className="button" href="#rating-methodology">Как считается рейтинг <Info size={16}/></a></div><div className="rating-filters" aria-label="Фильтры рейтинга"><label className="field">Категория<select className="select" value={category} onChange={e=>set({category:e.target.value||null})}><option value="">Все категории</option>{categories.map(c=><option value={c.slug} key={c.slug}>{c.name}</option>)}</select></label><label className="field">Город<select className="select" value={city} onChange={e=>set({city:e.target.value||null})}>{cities.map(c=><option value={c.slug} key={c.slug}>{c.name}</option>)}</select></label><label className="field">Период<select className="select" value={period} onChange={e=>set({period:e.target.value})}><option value="month">Месяц</option><option value="year">Год</option></select></label><div className="rating-filter-context"><span className="badge">{selectedCity}</span><span className="meta">{periodLabel} · {list.length} профилей</span></div></div>{fallback&&<div className="empty rating-empty"><h3>В выбранном городе пока нет рейтинга</h3><p>Показываем профили этой категории из других городов. Снимите фильтр города или выберите другую категорию.</p><div className="row wrap"><button className="button" onClick={()=>set({city:null})}>Показать все города</button><button className="button" onClick={()=>set({category:null})}>Сбросить категорию</button></div></div>}<section className="section rating-section" aria-labelledby="rating-top-title"><div className="section-head"><div><h2 id="rating-top-title">Топ-3</h2><span className="meta">Лидеры за период «{periodLabel.toLowerCase()}»</span></div><span className="rating-updated meta">Обновлено 18 сентября 2026</span></div><div className="rating-top-grid">{top.map((r,i)=>{const p=profiles.find(p=>p.id===r.profileId)!;const reviewCount=reviews.filter(review=>review.profileId===p.id).length;return <article className={`card rating-top-card ${i===0?'rating-top-first':''}`} key={r.id}><div className="rating-place"><span className="icon-meta"><Trophy size={16}/> Место {i+1}</span>{p.verified&&<span className="badge verified">Проверен</span>}</div><Link className="rating-person" href={`/profiles/${p.slug}`}><img className="avatar large" src={p.avatar} alt=""/><span><b>{p.name}</b><small>{p.specialty} · {cityName(p.city)}</small></span></Link><div className="rating-score-line"><strong>{r.score.toLocaleString('ru-RU')}</strong><span>баллов</span><span className="rating-stars icon-meta"><Star size={14} weight="fill"/> {p.rating.toFixed(1)}</span><span className="meta icon-meta"><ChatCircle size={13}/> {reviewCount} отзывов</span></div><div className="rating-top-actions"><Link className="button" href={`/profiles/${p.slug}`}>Открыть профиль <ArrowRight size={15}/></Link><button className="button" onClick={()=>app.open('score',{profileId:p.id})}>Состав score <Info size={15}/></button></div></article>})}</div></section><section className="section rating-section" aria-labelledby="rating-list-title"><div className="section-head"><div><h2 id="rating-list-title">Весь список</h2><span className="meta">{list.length} профилей · сортировка по score</span></div><span className="meta rating-legend"><TrendUp size={15}/> рост <TrendDown size={15}/> снижение</span></div><div className="card rating-list" role="table" aria-label="Таблица рейтинга"><div className="rating-list-head" role="row"><span>Место</span><span>Профессионал</span><span>Динамика</span><span>Score</span></div>{list.map((r,i)=>{const p=profiles.find(p=>p.id===r.profileId)!;const reviewCount=reviews.filter(review=>review.profileId===p.id).length;return <div className="rank-row rating-row" role="row" tabIndex={0} key={r.id} onKeyDown={e=>{if(e.key==='Enter')router.push(`/profiles/${p.slug}`)}}><span className="rating-rank" title="Позиция за выбранный период">#{i+1}</span><Link href={`/profiles/${p.slug}`} className="rating-profile" role="cell"><img className="avatar" src={p.avatar} alt=""/><span><b>{p.name}</b><small>{p.specialty} · {cityName(p.city)}{p.verified?' · Проверен':''}</small></span></Link><span className={`rating-movement ${r.movement>0?'positive':r.movement<0?'negative':''}`} title="Изменение за выбранный период">{r.movement>0?<><TrendUp size={15}/> +{r.movement}</>:r.movement<0?<><TrendDown size={15}/> {r.movement}</>:<>—</>} <small>за период</small></span><div className="rating-score-actions"><Link className="rating-review-link" href={`/profiles/${p.slug}?tab=reviews#reviews`} title="Открыть отзывы"><Star size={13} weight="fill"/> {p.rating.toFixed(1)} <ChatCircle size={13}/> {reviewCount}</Link><button className="button rating-score-button" aria-label={`Открыть score ${r.score.toLocaleString('ru-RU')} для ${p.name}`} onClick={()=>app.open('score',{profileId:p.id})}>{r.score.toLocaleString('ru-RU')} <Info size={14}/></button></div></div>})}</div></section><section className="section rating-methodology" id="rating-methodology" aria-labelledby="rating-method-title"><div className="section-head"><div><div className="eyebrow">Прозрачная методика</div><h2 id="rating-method-title">Как считается рейтинг</h2></div><span className="meta">demo-методика · {periodLabel}</span></div><p className="lede">Итоговый score — сумма пяти факторов. Значения в этом investor demo вымышлены и нужны, чтобы показать принцип сравнения.</p><div className="rating-factor-grid">{factorLabels.map(f=>{const sample=top[0]?.breakdown[f.key]??0;return <article className="card rating-factor" key={f.key}><div className="between"><h3>{f.label}</h3><b>{sample.toLocaleString('ru-RU')}</b></div><div className="rating-factor-bar"><span style={{width:`${Math.min(100,Math.round(sample/300))}%`}}/></div><p>{f.help}</p></article>})}</div><p className="meta rating-method-note">Сумма факторов равна score профиля. Оценка помогает сравнить открытые данные, но не заменяет личную проверку исполнителя.</p></section></div>}

function Collections(){const app=useApp();return <div className="container page"><div className="eyebrow">Личные подборки</div><div className="between wrap"><div><h1>Коллекции Софьи</h1><p className="lede">Сохраняйте проекты в подборки. Изменения остаются в этом браузере.</p></div><button className="button primary" onClick={()=>app.open('collection',{projectId:projects[0].id})}><Plus size={17}/> Создать коллекцию</button></div><div className="grid section">{app.collections.map(c=><Link className="card" href={`/collections/${c.slug}`} key={c.slug}><img className="media" style={{height:180}} src={mediaById(projects.find(p=>p.id===c.projectIds[0])?.mediaIds[0]??projects[0].mediaIds[0]).src} alt=""/><div className="card-body"><h2 style={{fontSize:20}}>{c.name}</h2><span className="meta">{c.projectIds.length} проектов →</span></div></Link>)}</div></div>}

function CollectionDetail({slug}:{slug:string}){const app=useApp();const c=app.collections.find(c=>c.slug===slug);if(!c)return <Missing/>;const items=c.projectIds.map(id=>projects.find(p=>p.id===id)!).filter(Boolean);return <div className="container page"><div className="eyebrow"><Link href="/collections">Коллекции</Link> / Подборка</div><h1>{c.name}</h1><p>{items.length} проектов · сохранено локально</p>{items.length?<div className="grid section">{items.map(p=><ProjectCard project={p} key={p.id}/>)}</div>:<div className="empty"><h2>Пока пусто</h2><p>Найдите проект в ленте и сохраните его сюда.</p><Link className="button" href="/feed">Открыть ленту</Link></div>}</div>}

function Me(){const app=useApp();const {search,set}=useUrl();const tab=qp(search,'tab','saved');const savedIds=[...new Set(app.collections.flatMap(c=>c.projectIds))];const saved=savedIds.map(id=>projects.find(p=>p.id===id)!).filter(Boolean);const recent=projects.slice(0,6);const unread=initialNotices.filter(n=>!app.readIds.includes(n.id)).length;const interests=['камерные свадьбы','editorial','botanical','лофты','фото'];const recommendations=profiles.filter(profile=>profile.city===app.city).slice(0,4);return <div className="container page viewer-page"><div className="viewer-hero"><div className="viewer-identity"><div className="viewer-avatar" aria-hidden="true">СБ</div><div><div className="eyebrow">Viewer-профиль</div><h1>Софья Белова</h1><p>Исследует проекты, собирает команды и сохраняет идеи для событий.</p><div className="viewer-location"><MapPin size={16}/><span>{cityName(app.city)}</span><button className="text-button" onClick={()=>app.open('city')}>Изменить город</button></div></div></div><div className="viewer-hero-actions"><Link className="button primary" href="/feed">Открыть ленту <ArrowRight size={16}/></Link><Link className="button" href="/settings">Настроить профиль <ArrowRight size={16}/></Link></div></div><div className="viewer-stats" aria-label="Статистика профиля"><div><BookmarkSimple size={18}/><b>{savedIds.length}</b><span>сохранённых проектов</span></div><div><SquaresFour size={18}/><b>{app.collections.length}</b><span>коллекций</span></div><div><Bell size={18}/><b>{unread}</b><span>непрочитанных</span></div><div><UserCircle size={18}/><b>Viewer</b><span>режим просмотра</span></div></div><div className="viewer-content-layout"><aside className="viewer-sidebar"><nav className="viewer-nav" aria-label="Разделы профиля"><Link className="viewer-nav-item active" href="/me"><span>Профиль</span><ArrowRight size={15}/></Link><Link className="viewer-nav-item" href="/collections"><span>Коллекции</span><span className="viewer-nav-count">{app.collections.length}</span></Link><Link className="viewer-nav-item" href="/notifications"><span>Уведомления</span>{unread>0&&<span className="viewer-nav-count unread">{unread}</span>}</Link><Link className="viewer-nav-item" href="/settings"><span>Настройки</span><ArrowRight size={15}/></Link></nav><div className="viewer-preferences card card-body"><div className="eyebrow">Ваши интересы</div><div className="viewer-interest-list">{interests.map(item=><Link className="chip" href={`/search?q=${encodeURIComponent(item)}`} key={item}>{item}</Link>)}</div><Link className="text-button" href="/settings">Изменить интересы <ArrowRight size={15}/></Link></div></aside><main className="viewer-main"><div className="tabs viewer-tabs" role="tablist" aria-label="Содержимое профиля"><button className={`chip ${tab==='saved'?'selected':''}`} role="tab" aria-selected={tab==='saved'} onClick={()=>set({tab:'saved'})}>Сохранённое</button><button className={`chip ${tab==='history'?'selected':''}`} role="tab" aria-selected={tab==='history'} onClick={()=>set({tab:'history'})}>Недавно смотрели</button></div>{tab==='saved'?<section className="viewer-section" aria-labelledby="saved-title"><div className="section-head"><div><div className="eyebrow">Подборки</div><h2 id="saved-title">Сохранённые проекты</h2></div><Link className="button" href="/collections">Все коллекции <ArrowRight size={15}/></Link></div>{saved.length?<div className="grid viewer-project-grid">{saved.slice(0,8).map(p=><ProjectCard key={p.id} project={p}/>)}</div>:<div className="empty viewer-empty"><h3>Здесь пока нет сохранённых проектов</h3><p>Сохраняйте понравившиеся идеи из ленты и собирайте их в коллекции.</p><Link className="button primary" href="/feed">Найти проекты</Link></div>}</section>:<section className="viewer-section" aria-labelledby="recent-title"><div className="section-head"><div><div className="eyebrow">История</div><h2 id="recent-title">Недавно смотрели</h2></div><span className="meta">локальная demo-история</span></div><div className="grid viewer-project-grid">{recent.map(p=><ProjectCard key={p.id} project={p}/>)}</div></section>}<section className="viewer-collections-preview" aria-labelledby="collections-preview-title"><div className="section-head"><div><div className="eyebrow">Организация</div><h2 id="collections-preview-title">Ваши коллекции</h2></div><Link className="text-button" href="/collections">Открыть все <ArrowRight size={15}/></Link></div><div className="viewer-collection-list">{app.collections.slice(0,3).map(c=><Link className="viewer-collection-row" href={`/collections/${c.slug}`} key={c.slug}><span className="viewer-collection-mark" aria-hidden="true">{c.name.slice(0,1)}</span><span><b>{c.name}</b><small>{c.projectIds.length} проектов · локально</small></span><ArrowRight size={16}/></Link>)}</div><section className="viewer-recommendations" aria-labelledby="recommendations-title"><div className="section-head"><div><div className="eyebrow">Подборка для вас</div><h2 id="recommendations-title">Профессионалы рядом с вашими интересами</h2></div><Link className="text-button" href="/pro">Открыть весь PRO <ArrowRight size={15}/></Link></div><div className="grid viewer-recommendation-grid">{recommendations.map(profile=><div key={profile.id}><ProfileCard profile={profile}/><p className="meta viewer-recommendation-reason">Совпадает с выбранным городом и локальными интересами</p></div>)}</div></section></section></main></div></div>}
function Notifications(){const app=useApp();const {search,set}=useUrl();const tab=qp(search,'tab','all');const unread=initialNotices.filter(n=>!app.readIds.includes(n.id));const visible=tab==='unread'?unread:initialNotices;const today=visible.filter(n=>n.date==='2026-09-18');const earlier=visible.filter(n=>n.date!=='2026-09-18');const markAll=()=>initialNotices.forEach(n=>app.markRead(n.id));return <div className="container page notifications-page"><div className="notifications-head"><div><div className="eyebrow">Локальные события</div><h1>Уведомления</h1><p className="lede">События о проектах, профилях и сохранённых подборках. Реальные сообщения никому не отправляются.</p></div><button className="button" disabled={!unread.length} onClick={markAll}>{unread.length?'Отметить всё прочитанным':'Всё прочитано'}</button></div><div className="tabs notifications-tabs" role="tablist" aria-label="Фильтр уведомлений"><button className={`chip ${tab==='all'?'selected':''}`} role="tab" aria-selected={tab==='all'} onClick={()=>set({tab:'all'})}>Все <span>{initialNotices.length}</span></button><button className={`chip ${tab==='unread'?'selected':''}`} role="tab" aria-selected={tab==='unread'} onClick={()=>set({tab:'unread'})}>Непрочитанные <span>{unread.length}</span></button></div>{visible.length?<div className="notifications-list">{today.length>0&&<section className="notification-group"><div className="notification-group-title"><h2>Сегодня</h2><span className="meta">{today.length}</span></div><div className="stack">{today.map(n=><NotificationItem key={n.id} notice={n} read={app.readIds.includes(n.id)} onRead={()=>app.markRead(n.id)}/>)}</div></section>}{earlier.length>0&&<section className="notification-group"><div className="notification-group-title"><h2>Ранее</h2><span className="meta">{earlier.length}</span></div><div className="stack">{earlier.map(n=><NotificationItem key={n.id} notice={n} read={app.readIds.includes(n.id)} onRead={()=>app.markRead(n.id)}/>)}</div></section>}</div>:<div className="empty notifications-empty"><h2>Непрочитанных уведомлений нет</h2><p>Когда в demo появится новое событие, оно будет показано здесь.</p><button className="button" onClick={()=>set({tab:'all'})}>Показать все уведомления</button></div>}</div>}
function NotificationItem({notice,read,onRead}:{notice:{id:string;title:string;body:string;href:string;date:string};read:boolean;onRead:()=>void}){return <article className={`card notification-card ${read?'is-read':'is-unread'}`}><span className="notification-dot" aria-hidden="true"><Bell size={15}/></span><div className="notification-copy"><div className="between"><h3>{notice.title}</h3><span className="meta">{notice.date}</span></div><p>{notice.body}</p><span className="badge">{read?'Прочитано':'Новое'}</span></div><div className="notification-actions"><Link className="button" href={notice.href} onClick={onRead}>Открыть <ArrowRight size={15}/></Link>{!read&&<button className="text-button" onClick={onRead}>Прочитано</button>}</div></article>}
function NotFoundPreview(){return <div className="container page"><div className="eyebrow">Системное состояние · Карта сайта</div><h1>Страница не найдена</h1><p className="lede">Проверьте адрес или вернитесь в ленту.</p><div className="row wrap"><Link className="button primary" href="/feed">Открыть ленту <ArrowRight size={16}/></Link><Link className="button" href="/settings?tab=sitemap">К карте сайта <ArrowRight size={16}/></Link></div></div>}
function ErrorPreview(){return <div className="container page"><div className="eyebrow">Системное состояние · Карта сайта</div><h1>Не удалось загрузить Chereda</h1><p className="lede">Это локальный preview состояния ошибки. Основные demo-данные не изменены.</p><div className="row wrap"><Link className="button primary" href="/feed">Вернуться в ленту <ArrowRight size={16}/></Link><Link className="button" href="/settings?tab=sitemap">К карте сайта <ArrowRight size={16}/></Link></div></div>}
function SitemapPanel(){const app=useApp();const sections=buildSiteMap(app.collections);return <div className="sitemap-page"><div className="sitemap-summary card card-body"><div><div className="eyebrow">Навигация по demo</div><h2>Карта сайта</h2><p>Маршруты сгруппированы по типам страниц. Для динамических сущностей показан один заполненный пример; остальные записи открываются из каталогов.</p></div><span className="badge">{siteMapEntryCount(app.collections)} типов страниц</span></div><div className="sitemap-sections">{sections.map(section=><section className="card card-body sitemap-section" key={section.title}><div className="section-head"><div><h2>{section.title}</h2><p className="meta">{section.description}</p></div><span className="badge">{section.entries.length}</span></div><div className="sitemap-grid">{section.entries.map(entry=><Link className="sitemap-link" href={entry.href} key={entry.href}><span className="sitemap-link-copy"><b>{entry.label}</b><small>{entry.description}</small></span><ArrowRight size={16} aria-hidden="true"/></Link>)}</div></section>)}</div></div>}
function Settings(){const app=useApp();const {search,set}=useUrl();const tab=qp(search,'tab','preferences');const interestOptions=['Проекты и кейсы','Площадки','Фото и видео','Beauty','Editorial','Botanical'];const [resetOpen,setResetOpen]=useState(false);const [selectedInterests,setSelectedInterests]=useState<string[]>(interestOptions.slice(0,4));useEffect(()=>{try{const raw=localStorage.getItem('chereda-viewer-interests');if(raw){const parsed=JSON.parse(raw);if(Array.isArray(parsed)){const next=parsed.filter((item):item is string=>typeof item==='string');queueMicrotask(()=>setSelectedInterests(next))}}}catch{}},[]);useEffect(()=>{localStorage.setItem('chereda-viewer-interests',JSON.stringify(selectedInterests))},[selectedInterests]);const toggleInterest=(item:string)=>setSelectedInterests(prev=>prev.includes(item)?prev.filter(value=>value!==item):[...prev,item]);const chooseTheme=(value:'light'|'dark'|'system')=>{app.setTheme(value);app.toast(`Тема: ${value==='light'?'светлая':value==='dark'?'тёмная':'системная'}`)};const chooseCity=(value:string)=>{app.setCity(value);app.toast(`Город: ${cityName(value)}`)};return <div className="container page settings-page"><div className="settings-intro"><div><div className="eyebrow">Ваше demo-пространство</div><h1>Настройки</h1><p className="lede">Управляйте темой, городом и локальным состоянием Viewer. Изменения сохраняются после обновления страницы.</p></div><Link className="button" href="/me">Вернуться в профиль <ArrowRight size={16}/></Link></div><div className="tabs settings-tabs" role="tablist" aria-label="Разделы настроек"><button className={`chip ${tab!=='sitemap'?'selected':''}`} role="tab" aria-selected={tab!=='sitemap'} onClick={()=>set({tab:null})}>Настройки</button><button className={`chip ${tab==='sitemap'?'selected':''}`} role="tab" aria-selected={tab==='sitemap'} onClick={()=>set({tab:'sitemap'})}>Карта сайта</button></div>{tab==='sitemap'?<SitemapPanel/>:<><div className="settings-layout"><section className="card card-body settings-card settings-theme-card"><div className="settings-card-head"><div><h2>Тема интерфейса</h2><p>Выберите режим отображения для всего Chereda.</p></div><span className="settings-current"><CheckCircle size={15}/> {app.theme==='light'?'Светлая':app.theme==='dark'?'Тёмная':'Системная'}</span></div><div className="settings-segmented" role="group" aria-label="Тема интерфейса">{(['system','light','dark'] as const).map(v=><button key={v} aria-pressed={app.theme===v} className={app.theme===v?'selected':''} onClick={()=>chooseTheme(v)}>{v==='system'?'Системная':v==='light'?'Светлая':'Тёмная'}</button>)}</div></section><section className="card card-body settings-card"><div className="settings-card-head"><div><h2>Ваш город</h2><p>Город влияет на локальные маркеры и подборку в ленте.</p></div><MapPin size={22} color="var(--brand-blue)"/></div><label className="field" htmlFor="settings-city">Основной город<select id="settings-city" className="select" value={app.city} onChange={e=>chooseCity(e.target.value)}>{cities.map(c=><option value={c.slug} key={c.slug}>{c.name}</option>)}</select></label><div className="settings-city-chips">{cities.slice(0,4).map(city=><button className={`chip ${app.city===city.slug?'selected':''}`} key={city.slug} onClick={()=>chooseCity(city.slug)}>{city.name}</button>)}</div></section><section className="card card-body settings-card"><div className="settings-card-head"><div><h2>Интересы и поиск</h2><p>Сейчас профиль настроен на визуальные события и подготовку команды.</p></div></div><div className="settings-interest-grid">{interestOptions.map(item=><button type="button" className={'settings-interest '+(selectedInterests.includes(item)?'selected':'')} key={item} onClick={()=>toggleInterest(item)} aria-pressed={selectedInterests.includes(item)}>{selectedInterests.includes(item)?<CheckCircle size={16}/>:<Plus size={16}/>} {item}</button>)}</div><Link className="text-button" href="/search">Перейти к поиску по интересам <ArrowRight size={15}/></Link></section><section className="card card-body settings-card settings-demo-card"><div className="settings-card-head"><div><h2>Демо-состояние</h2><p>Сброс возвращает коллекции, реакции, город, тему и уведомления к начальным данным.</p></div><span className="badge">Только локально</span></div><button className="button danger-button" onClick={()=>setResetOpen(true)}>Сбросить demo-state</button></section></div>{resetOpen&&<div className="settings-confirm-backdrop" role="presentation"><div className="settings-confirm" role="alertdialog" aria-modal="true" aria-labelledby="settings-confirm-title"><div className="eyebrow">Подтверждение</div><h2 id="settings-confirm-title">Сбросить demo-состояние?</h2><p>Сохраняемые проекты, город, тема и прочитанные уведомления вернутся к начальным значениям.</p><div className="row settings-confirm-actions"><button className="button" onClick={()=>setResetOpen(false)}>Отмена</button><button className="button danger-button" onClick={app.reset}>Сбросить</button></div></div></div>}</>}</div>}
function About(){const app=useApp();const project=projectBySlug('white-garden-wedding')??projects[0];const credits=creditsFor(project.id);const creditProfiles=credits.map(c=>({credit:c,profile:profiles.find(p=>p.id===c.profileId)})).filter(v=>v.profile);return <div className="container page about-page">



<section className="about-hero" id="about-hero" aria-labelledby="about-hero-title"><div className="about-hero-copy"><div className="eyebrow">О проекте Chereda</div><h1 id="about-hero-title"><span className="sr-only">От вдохновения к команде. </span>Chereda — единый поиск людей, площадок и команд для событий</h1><p className="lede">Найдите идею, откройте проект, увидьте всех участников и свяжитесь с нужным специалистом — от фотографа и площадки до декора, укладки и кейтеринга.</p><p>Мы собираем event-индустрию вокруг результата, а не вокруг разрозненных публикаций.</p><div className="row wrap"><Link className="button primary" href="/feed">Посмотреть проекты <ArrowRight size={17}/></Link><Link className="button pro" aria-label="Открыть PRO" href="/pro">Открыть PRO-поиск <ArrowRight size={17}/></Link><a className="about-text-link" href="#about-mechanics">Как это работает <ArrowRight size={16}/></a></div><div className="about-signal-strip" aria-label="Ключевая механика Chereda"><span><b>Проект</b><small>один кейс</small></span><span><b>Команда</b><small>все роли</small></span><span><b>Контакт</b><small>с контекстом</small></span></div></div><div className="about-hero-demo"><div className="about-demo-label">Вдохновение → проект → команда</div><ProjectCard project={project} /><div className="about-credit-list" aria-label="Участники проекта"><b>Участники «Белого сада»</b>{creditProfiles.slice(0,5).map(({credit,profile})=><Link href={`/profiles/${profile!.slug}`} key={credit.id}><span>{credit.roleLabel}</span><strong>{profile!.name}</strong></Link>)}<Link className="about-see-all" href={`/projects/${project.slug}#team`}>Все {credits.length} участника <ArrowRight size={15}/></Link></div></div></section>



<section className="about-section about-problem" id="about-problem" aria-labelledby="about-problem-title"><div><div className="eyebrow">Проблема</div><h2 id="about-problem-title">Событие создают десятки специалистов. Найти их всех обычно невозможно.</h2><p className="lede">Фотограф публикует съёмку в одной соцсети. Площадка живёт на другом сайте. Декоратор показывает только свои детали. Стилист, ведущий, кейтеринг и техническая команда остаются за кадром. В результате клиент видит красивую картинку, но не понимает, кто создал результат и к кому обратиться.</p></div><ul className="about-bullet-grid"><li><CheckCircle size={16} aria-hidden="true"/><span>Подрядчики разбросаны по разным платформам.</span></li><li><CheckCircle size={16} aria-hidden="true"/><span>Поиск плохо учитывает город, выезд, бюджет и специализацию.</span></li><li><CheckCircle size={16} aria-hidden="true"/><span>Старые каталоги содержат закрытые площадки и устаревшие цены.</span></li><li><CheckCircle size={16} aria-hidden="true"/><span>Участники одного проекта не связаны между собой.</span></li><li><CheckCircle size={16} aria-hidden="true"/><span>Социальный профиль не заменяет профессиональное портфолио.</span></li><li><CheckCircle size={16} aria-hidden="true"/><span>Клиент собирает команду по крупицам.</span></li></ul><a className="about-inline-cta" href="#about-mechanics">Посмотреть, как Chereda собирает проект <ArrowRight size={16}/></a></section>



<section className="about-section" id="about-mechanics" aria-labelledby="about-mechanics-title"><div className="section-head"><div><div className="eyebrow">Механика</div><h2 id="about-mechanics-title">Один проект. Все участники. Один понятный путь.</h2></div><Link className="button" aria-label="Открыть пример — проект «Белый сад»" href={`/projects/${project.slug}`}>Открыть проект «Белый сад» <ArrowRight size={16}/></Link></div><div className="about-flow"><ol>{['Увидьте понравившееся изображение.','Откройте проект и изучите весь кейс.','Посмотрите участников, роли и вклад.','Проверьте город, выезд, цену, стиль и рейтинг.','Сохраните, сравните или отправьте запрос.'].map((step,i)=><li key={step}><b>0{i+1}</b><span>{step}</span></li>)}</ol><div className="about-team-preview"><div className="about-team-preview-head"><span>Команда проекта</span><b>{credits.length} участников</b></div>{creditProfiles.slice(0,9).map(({credit,profile})=><Link href={`/profiles/${profile!.slug}`} key={credit.id}><span className="about-role-chip">{credit.roleLabel}</span><span>{profile!.name}</span><ArrowRight size={14}/></Link>)}</div></div><div className="about-role-tags">{['Площадка','Декор','Фото и видео','Beauty','Программа','Техника и сервис'].map(label=><span className="chip" key={label}>{label}</span>)}</div></section>



<section className="about-section" id="about-viewer" aria-labelledby="about-viewer-title"><div className="eyebrow">Для клиента</div><h2 id="about-viewer-title">Сначала найдите то, что вам нравится. Потом — тех, кто может это создать.</h2><p className="lede">Chereda помогает начинать не с бесконечного списка услуг, а с визуального результата. Вы сохраняете проект, сравниваете его участников и сразу видите, кто работает в вашем городе, сколько стоит услуга и какие специалисты могут дополнить выбранную команду.</p><div className="about-benefit-grid">{[['Визуальный поиск','Ищите через проекты, фотографии, стили и реальные форматы событий.'],['Связная команда','Один проект показывает не только главного автора, но и всех участников производства.'],['Понятное доверие','Отзывы, рейтинг, верификация, открытые цены и credits помогают сравнивать осознанно.'],['География','Сразу видны город, готовность к выезду и подходящий формат работы.']].map(([title,text])=><article className="card card-body" key={title}><h3>{title}</h3><p>{text}</p></article>)}</div><div className="about-geo-strip" aria-label="Demo-география и условия выбора"><div><div className="eyebrow">Demo-география</div><b>Город, выезд и формат работы видны до контакта</b></div><div className="about-geo-pills">{cities.slice(0,5).map(city=><span className="chip" key={city.slug}>{city.name}</span>)}</div></div><Link className="button" href="/search">Найти идею для своего события <ArrowRight size={16}/></Link></section>



<section className="about-section" id="about-pros" aria-labelledby="about-pros-title"><div className="eyebrow">Для профессионала</div><h2 id="about-pros-title">Ваш профиль — не просто страница. Это рабочая точка входа в новые проекты.</h2><p className="lede">Профессионал получает структурированный профиль с портфолио, услугами, ценами, географией, контактами, отзывами и кейсами. Если он участвовал в общем проекте, его вклад становится видимым рядом с остальными участниками.</p><div className="about-pros-layout"><ul className="about-check-list">{['Единая страница вместо разрозненных ссылок.','Поиск по городу, бюджету, стилю и специализации.','Кейсы связывают специалиста с другими профессионалами.','Клиент приходит с контекстом уже понравившегося проекта.','Цены и условия видны до первого контакта.','Рейтинг и отзывы формируют доверие.'].map(item=><li key={item}><CheckCircle size={16} aria-hidden="true"/><span>{item}</span></li>)}</ul><div className="card card-body about-pros-callout"><h3>Следующий этап</h3><p>Позже на платформе могут появиться биржа запросов и рабочие инструменты. Сейчас это Viewer-demo без кабинета профессионала.</p><button className="button pro" onClick={()=>app.open('partner')}>Узнать о размещении <ArrowRight size={16}/></button></div></div></section>



<section className="about-section about-pro" id="about-pro" aria-labelledby="about-pro-title"><div className="about-pro-copy"><div className="eyebrow">PRO</div><h2 id="about-pro-title">От визуального вдохновения — к точному подбору под задачу.</h2><p className="lede">В PRO-режиме можно выбирать категорию, специализацию, город, выезд, бюджет, рейтинг, наличие портфолио и отраслевые параметры.</p><Link className="button pro" aria-label="Открыть каталог профессионалов" href="/pro">Открыть PRO-каталог <ArrowRight size={16}/></Link></div><div className="about-task-list">{['Площадка на 80–150 гостей в Москве.','Фотограф с editorial-стилем и выездом.','Beauty-команда на утро свадебного дня.','Сценическое, световое и звуковое оборудование.','Кейтеринг с конкретной стоимостью на человека.','Подрядчик в другом городе с готовностью приехать.'].map(task=><div key={task}><span>PRO</span><p>{task}</p></div>)}</div></section>



<section className="about-section" id="about-difference" aria-labelledby="about-difference-title"><div className="eyebrow">Отличие</div><h2 id="about-difference-title">Chereda соединяет то, что обычно существует отдельно.</h2><div className="about-compare" role="table" aria-label="Сравнение подходов"><div className="about-compare-head" role="row"><b role="columnheader">Обычный сценарий</b><b role="columnheader">Chereda</b></div>{[['Фото живёт отдельно от исполнителя','Фото связано с проектом и credits'],['Видно одного автора','Видна вся команда'],['Профиль — просто витрина','Профиль связан с кейсами, услугами и рейтингом'],['Поиск по общим словам','Поиск по городу, стилю, бюджету и параметрам'],['Цена часто скрыта','Цена и единица цены открыты, если указаны'],['Роли события находятся отдельно','Все роли раскрываются в одной сущности'],['Рекомендации выглядят случайными','У рекомендации есть понятная причина']].map(([a,b])=><div className="about-compare-row" role="row" key={a}><span role="cell">{a}</span><strong role="cell">{b}</strong></div>)}</div><p className="about-note">В заявленной конфигурации — визуальный поиск, единый проект, все credits и глубокий event-каталог — у Chereda есть возможность занять отдельную нишу между вдохновляющей лентой, профессиональным каталогом и рабочей страницей команды.</p></section>



<section className="about-section" id="about-growth" aria-labelledby="about-growth-title"><div className="eyebrow">Потенциал</div><h2 id="about-growth-title">Чем больше проектов и участников, тем полезнее становится поиск.</h2><div className="about-growth-layout"><ol className="about-growth-steps">{['Профессионалы размещают профили и портфолио.','Проекты связывают разные категории.','Клиенты находят исполнителей через визуальный контент.','Отзывы, credits и цены повышают качество выбора.','Новые проекты усиливают рекомендации и поиск.','Профессионалы получают новые обращения и связи.'].map((step,i)=><li key={step}><b>{i+1}</b><span>{step}</span></li>)}</ol><div className="card card-body"><h3>Roadmap</h3><p>Следующие направления развития:</p><div className="about-roadmap-tags">{['Новые города и страны','Профессиональные страницы','Биржа запросов','Подбор команды','Аналитика','Verified data'].map(item=><span className="badge" key={item}>{item}</span>)}</div><small className="meta">Roadmap — будущие возможности, не текущая функциональность demo.</small></div></div></section>



<section className="about-section about-final" id="about-contact" aria-labelledby="about-contact-title"><div className="eyebrow">Следующий шаг</div><h2 id="about-contact-title">Собирайте события вокруг людей, которые их создают.</h2><p className="lede">Исследуйте проекты, находите исполнителей, развивайте профессиональные связи и помогайте event-индустрии становиться прозрачнее.</p><div className="about-final-actions"><Link className="button primary" href="/feed">Исследовать проекты <ArrowRight size={16}/></Link><Link className="button" href="/search">Найти специалиста <ArrowRight size={16}/></Link><Link className="button pro" aria-label="Перейти в PRO-каталог" href="/pro">Открыть PRO-поиск <ArrowRight size={16}/></Link><button className="button" onClick={()=>app.open('partner')}>Предложить партнёрство <ArrowRight size={16}/></button></div></section>



</div>}



function DemoHub(){const app=useApp();return <div className="container page"><div className="eyebrow">Investor demo</div><h1>Пройдите Chereda за шесть минут</h1><p className="lede">Четыре подготовленных сценария демонстрируют путь от кадра к контакту, глубокий поиск, сохранение и объяснение продукта.</p><div className="grid section">{[['1','Из визуала в команду','/feed?tab=for-you','Белый сад → десять участников → Елена → заявка'],['2','Профессиональный поиск','/pro/venues?city=moscow&capacity=80-150&priceMax=500000&outsideCatering=1','Площадки → фильтры → Берег → рейтинг'],['3','Сохранение и город','/projects/white-garden-wedding','Сохранить → коллекция → город → тема'],['4','Объяснение Chereda','/about','Механизм → пример → PRO']].map(([n,title,href,body])=><Link className="card card-body" href={href} key={n}><span className="eyebrow">Сценарий {n}</span><h2>{title}</h2><p>{body}</p><span className="button">Начать <ArrowRight size={17}/></span></Link>)}</div>{section('Проверить состояния',<div className="row wrap"><Link className="button" href="/feed?state=loading">Загрузка</Link><Link className="button" href="/feed?state=empty">Пусто</Link><Link className="button" href="/feed?state=error">Ошибка и retry</Link><Link className="button" href="/search?q=несуществующий-запрос">Нет результатов</Link><Link className="button" href="/profiles/unknown">Неизвестный профиль</Link><Link className="button" href="/unknown">Страница 404</Link><button className="button" onClick={()=>app.toast('Это локальное demo-уведомление')}>Toast</button></div>)}{section('Управление demo',<div className="row wrap"><button className="button" onClick={()=>app.setTheme(app.theme==='dark'?'light':'dark')}>{app.theme==='dark'?<Sun size={18}/>:<Moon size={18}/>} Сменить тему</button><button className="button" onClick={app.reset}><Trash size={18}/> Сбросить demo-state</button></div>)}</div>}

















function RegisterPage(){
  const router=useRouter()
  const [role,setRole]=useState<'viewer'|'professional'>('viewer')
  const [name,setName]=useState('')
  const [city,setCity]=useState('moscow')
  const [submitted,setSubmitted]=useState(false)
  const submit=(event:React.FormEvent)=>{
    event.preventDefault()
    localStorage.setItem('chereda-onboarding',JSON.stringify({role,name:name.trim()||'Новый участник',city,createdAt:new Date().toISOString()}))
    setSubmitted(true)
  }
  return <div className="container page onboarding-page">
    <div className="hero onboarding-hero"><div className="eyebrow">Новый участник</div><h1>Начните с того, что хотите найти или создать</h1><p className="lede">Это demo-onboarding Chereda. Он не создаёт настоящий аккаунт и сохраняет данные только в этом браузере.</p></div>
    <div className="onboarding-layout">
      <section className="card card-body onboarding-card">
        {submitted?<div className="empty"><CheckCircle size={42} color="var(--success)"/><h2>Профиль demo создан</h2><p>{role==='professional'?'Теперь заполните страницу профессионала и посмотрите preview.':'Можно исследовать проекты и собирать коллекции.'}</p><div className="row wrap"><button className="button primary" onClick={()=>router.push(role==='professional'?'/professional':'/feed')}>{role==='professional'?'Открыть конструктор':'Открыть ленту'} <ArrowRight size={16}/></button><button className="button" onClick={()=>setSubmitted(false)}>Изменить данные</button></div></div>:<form onSubmit={submit} className="stack"><div className="field"><span>Кем вы приходите в Chereda</span><div className="onboarding-role-grid"><button type="button" className={'onboarding-role '+(role==='viewer'?'selected':'')} onClick={()=>setRole('viewer')}><UserCircle size={22}/><b>Исследователь</b><small>Ищу проекты, людей и идеи</small></button><button type="button" className={'onboarding-role '+(role==='professional'?'selected':'')} onClick={()=>setRole('professional')}><Briefcase size={22}/><b>Профессионал</b><small>Показываю портфолио и услуги</small></button></div></div><label className="field">Имя или название<input className="input" value={name} onChange={e=>setName(e.target.value)} placeholder="Например, Софья Белова" required/></label><label className="field">Основной город<select className="select" value={city} onChange={e=>setCity(e.target.value)}>{cities.map(item=><option value={item.slug} key={item.slug}>{item.name}</option>)}</select></label><button className="button primary" type="submit">Продолжить <ArrowRight size={16}/></button></form>}
      </section>
      <aside className="card card-body onboarding-side"><div className="eyebrow">Что дальше</div><h2>{role==='professional'?'Соберите страницу, которую увидит клиент':'Сохраните первую идею'}</h2><p>{role==='professional'?'Добавьте специализацию, услуги, цены, географию и стили. Всё можно изменить в demo-конструкторе.':'После onboarding откроется лента с визуальными кейсами, командами и локальными рекомендациями.'}</p><div className="stack onboarding-benefits"><span><CheckCircle size={16}/> Связные проекты и профили</span><span><CheckCircle size={16}/> Город и цена видны до контакта</span><span><CheckCircle size={16}/> Данные остаются локальными</span></div></aside>
    </div>
  </div>
}

function ProfessionalPage(){
  const app=useApp()
  const [saved,setSaved]=useState(false)
  const [name,setName]=useState('Анна Миронова')
  const [type,setType]=useState('Специалист')
  const [city,setCity]=useState(app.city)
  const [specialty,setSpecialty]=useState('Фотограф')
  const [bio,setBio]=useState('Создаю визуальные истории и собираю вокруг них сильную команду.')
  const [tags,setTags]=useState('editorial, botanical')
  const [styles,setStyles]=useState('editorial, современный')
  const [service,setService]=useState('Съёмка события')
  const [price,setPrice]=useState('120000')
  const [verified,setVerified]=useState(true)
  const [social,setSocial]=useState('site.example/demo')
  const save=(event:React.FormEvent)=>{event.preventDefault();localStorage.setItem('chereda-professional-profile',JSON.stringify({name,type,city,specialty,bio,tags,styles,service,price,verified,social}));setSaved(true);app.toast('Профиль сохранён локально')}
  return <div className="container page professional-page">
    <div className="professional-head"><div><div className="eyebrow">Профиль-конструктор</div><h1>Страница профессионала</h1><p className="lede">Заполните данные, которые клиент видит в PRO: специализация, кейсы, услуги, цена, география и доверие.</p></div><div className="row wrap"><Link className="button" href="/register">Изменить роль</Link><Link className="button" href="/pro">Открыть PRO <ArrowRight size={16}/></Link></div></div>
    <div className="professional-layout"><form className="card card-body professional-form stack" onSubmit={save}><div className="professional-form-section"><h2>Основное</h2><label className="field">Имя или название<input className="input" value={name} onChange={e=>setName(e.target.value)}/></label><label className="field">Тип профиля<select className="select" value={type} onChange={e=>setType(e.target.value)}><option>Специалист</option><option>Команда</option><option>Агентство</option><option>Площадка</option></select></label><label className="field">Специализация<input className="input" value={specialty} onChange={e=>setSpecialty(e.target.value)}/></label><label className="field">Город<select className="select" value={city} onChange={e=>setCity(e.target.value)}>{cities.map(item=><option value={item.slug} key={item.slug}>{item.name}</option>)}</select></label><label className="field">Описание<textarea className="textarea" value={bio} onChange={e=>setBio(e.target.value)}/></label></div><div className="professional-form-section"><h2>Теги и стили</h2><label className="field">Теги<input className="input" value={tags} onChange={e=>setTags(e.target.value)}/><small>Разделяйте значения запятыми</small></label><label className="field">Стили<input className="input" value={styles} onChange={e=>setStyles(e.target.value)}/></label></div><div className="professional-form-section"><h2>Услуги и цена</h2><label className="field">Основная услуга<input className="input" value={service} onChange={e=>setService(e.target.value)}/></label><label className="field">Цена от, ₽<input className="input" inputMode="numeric" value={price} onChange={e=>setPrice(e.target.value)}/></label><label className="field">Сайт или соцсеть<input className="input" value={social} onChange={e=>setSocial(e.target.value)}/></label><label className="row"><input type="checkbox" checked={verified} onChange={e=>setVerified(e.target.checked)}/> Показать demo-метку «Проверен»</label></div><button className="button pro" type="submit">{saved?<><CheckCircle size={17}/> Сохранено</>:<>Сохранить preview <ArrowRight size={16}/></>}</button></form>
      <aside className="professional-preview"><div className="section-head"><div><div className="eyebrow">Публичный preview</div><h2>Так страницу увидит клиент</h2></div><span className="badge pro">PRO</span></div><article className="card professional-preview-card"><div className="professional-preview-cover"></div><div className="card-body"><div className="row"><div className="viewer-avatar">АM</div><div><div className="profile-title-line"><h2>{name}</h2>{verified&&<span className="badge verified"><CheckCircle size={14}/> Проверен</span>}</div><div className="meta">{specialty} · {cityName(city)}</div></div></div><p>{bio}</p><div className="professional-preview-facts"><span className="fact"><MapPin size={15}/> {cityName(city)}</span><span className="fact"><CurrencyRub size={15}/> от {Number(price||0).toLocaleString('ru-RU')} ₽</span><span className="fact"><Star size={15}/> 4.9</span></div><div className="profile-style-row">{tags.split(',').map(item=>item.trim()).filter(Boolean).map(item=><span className="chip" key={item}>{item}</span>)}</div><div className="card professional-service-preview"><div className="between"><b>{service}</b><span className="badge">Основная</span></div><p>Условия, формат и состав согласуются до события.</p><strong>от {Number(price||0).toLocaleString('ru-RU')} ₽</strong></div><div className="row wrap"><button type="button" className="button pro" onClick={()=>app.toast('Demo-заявка откроется после публикации профиля')}>Связаться</button><button type="button" className="button" onClick={()=>app.toast('Ссылка preview скопирована')}>Поделиться</button></div></div></article><div className="card card-body professional-checklist"><h3>Профиль заполнен на 80%</h3><p>Добавьте 3–5 кейсов и подтвердите контакты на следующем этапе.</p><div className="profile-progress"><span style={{width:'80%'}}></span></div></div></aside>
    </div>
  </div>
}


function Recommendations(){
  const app=useApp()
  const profilesForYou=profiles.filter(profile=>profile.city===app.city).slice(0,6)
  const projectsForYou=projects.filter(project=>project.city===app.city||project.styles.includes('editorial')).slice(0,6)
  return <div className="container page recommendations-page"><div className="hero"><div className="eyebrow">Персональная подборка</div><h1>Рекомендации для вас</h1><p className="lede">Подборка строится по городу, интересам и сохранённым проектам. В demo причина рекомендации всегда видна рядом с карточкой.</p><div className="row wrap"><button className="button" onClick={()=>app.open('city')}><MapPin size={17}/> Город: {cityName(app.city)}</button><Link className="button pro" href="/pro">Уточнить в PRO <ArrowRight size={16}/></Link></div></div><section className="section"><div className="section-head"><div><div className="eyebrow">Люди и команды</div><h2>Подходят по городу и стилю</h2></div><Link className="text-button" href="/subscriptions">Мои подписки <ArrowRight size={15}/></Link></div><div className="grid recommendation-profile-grid">{profilesForYou.map(profile=><div key={profile.id}><ProfileCard profile={profile}/><p className="meta recommendation-reason">Совпадает с городом {cityName(app.city)} и выбранными интересами</p></div>)}</div></section><section className="section"><div className="section-head"><div><div className="eyebrow">Проекты</div><h2>Визуальные идеи для продолжения поиска</h2></div><Link className="text-button" href="/feed">Открыть ленту <ArrowRight size={15}/></Link></div><div className="grid recommendation-project-grid">{projectsForYou.map(project=><div key={project.id}><ProjectCard project={project}/><p className="meta recommendation-reason">Похожий формат или стиль проекта</p></div>)}</div></section></div>
}

function Subscriptions(){
  const app=useApp()
  const [ids,setIds]=useState<string[]>(['anna-mironova','loft-bereg'])
  useEffect(()=>{try{const raw=localStorage.getItem('chereda-subscriptions');if(raw){const parsed=JSON.parse(raw);if(Array.isArray(parsed))queueMicrotask(()=>setIds(parsed.filter((v):v is string=>typeof v==='string')))}}catch{}},[])
  const toggle=(id:string)=>setIds(prev=>{const next=prev.includes(id)?prev.filter(v=>v!==id):[...prev,id];localStorage.setItem('chereda-subscriptions',JSON.stringify(next));app.toast(next.includes(id)?'Подписка добавлена':'Подписка снята');return next})
  const list=profiles.filter(profile=>ids.includes(profile.id))
  const suggested=profiles.filter(profile=>!ids.includes(profile.id)&&profile.city===app.city).slice(0,4)
  return <div className="container page subscriptions-page"><div className="eyebrow">Профиль Viewer</div><div className="between wrap"><div><h1>Подписки</h1><p className="lede">Следите за профессионалами и командами, чьи проекты хотите видеть в ленте.</p></div><Link className="button" href="/recommendations">Рекомендации <ArrowRight size={16}/></Link></div><section className="section"><div className="section-head"><h2>Вы подписаны</h2><span className="meta">{list.length}</span></div>{list.length?<div className="grid">{list.map(profile=><div key={profile.id}><ProfileCard profile={profile}/><button className="button subscription-toggle" onClick={()=>toggle(profile.id)}>Отписаться</button></div>)}</div>:<div className="empty"><h3>Подписок пока нет</h3><p>Откройте рекомендации и подпишитесь на подходящие профили.</p><Link className="button primary" href="/recommendations">Найти профили</Link></div>}</section><section className="section"><div className="section-head"><div><div className="eyebrow">Рядом</div><h2>Кого можно добавить</h2></div></div><div className="grid">{suggested.map(profile=><div key={profile.id}><ProfileCard profile={profile}/><button className="button pro subscription-toggle" onClick={()=>toggle(profile.id)}>Подписаться</button></div>)}</div></section></div>
}

