  const toggle=(id:string)=>setIds(prev=>{const next=prev.includes(id)?prev.filter(v=>v!==id):[...prev,id];localStorage.setItem('chereda-favorites-pro',JSON.stringify(next));app.toast(next.includes(id)?'Профиль добавлен в избранное PRO':'Профиль убран из избранного PRO');return next})
